sect2.example:
    Utilizzo di self::


<?php

class A
{
    public static function who()
    {
        echo __CLASS__;
    }

    public static function test()
    {
        self::who();
    }
}

class B extends A
{
    public static function who()
    {
        echo __CLASS__;
    }
}

B::test();

?>


    &example.outputs;


A

    Utilizzo semplice di static::


<?php

class A
{
    public static function who()
    {
        echo __CLASS__;
    }

    public static function test()
    {
        static::who(); // Qui entrano in gioco i Late Static Bindings
    }
}

class B extends A
{
    public static function who()
    {
        echo __CLASS__;
    }
}

B::test();

?>


    &example.outputs;


B

    Utilizzo di static:: in un contesto non statico


<?php

class A
{
    private function foo()
    {
        echo "Success!\n";
    }

    public function test()
    {
        $this->foo();
        static::foo();
    }
}

class B extends A
{
    /* foo() verrà copiato in B, quindi il suo scope rimarrà A e
    * la chiamata avrà successo */
}

class C extends A
{
    private function foo()
    {
        /* Il metodo originale viene sostituito; lo scope del nuovo è C */
    }
}

$b = new B();
$b->test();

$c = new C();
try {
    $c->test();
} catch (Error $e) {
    echo $e->getMessage();
}

?>


    &example.outputs;


Success!
Success!
Success!
Call to private method C::foo() from scope A

note.example:
     Chiamate di inoltro e non di inoltro


<?php

class A
{
    public static function foo()
    {
        static::who();
    }

    public static function who()
    {
        echo __CLASS__ . "\n";
    }
}

class B extends A
{
    public static function test()
    {
        A::foo();
        parent::foo();
        self::foo();
    }

    public static function who()
    {
        echo __CLASS__ . "\n";
    }
}

class C extends B
{
    public static function who()
    {
        echo __CLASS__ . "\n";
    }
}

C::test();

?>


     &example.outputs;


A
C
C
